export const dashboardDiagram="import {escapeHTML as esc,layoutGraph,nodeStates,friendlyIdentity} from './model.mjs';\nfunction lines(label,max=27){const result=[];let line='';for(const word of String(label).split(/\\s+/)){if(line&&line.length+word.length>max){result.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)result.push(line);if(result.length>2)result[1]=result.slice(1).join(' ').slice(0,max-1)+'…';return result.slice(0,2);}\nconst types={start:['Start','event','M7 4l10 8-10 8z'],end:['Finish','event','M6 6h12v12H6z'],terminate:['Finish','event','M6 6h12v12H6z'],service:['Action','service','M5 5h14v14H5z M9 9h6v6H9z'],call:['Subprocess','call','M4 7h13v13H4z M8 3h12v13'],human:['Human review','human','M8 7a4 4 0 1 0 8 0 4 4 0 1 0-8 0 M5 21v-2a7 7 0 0 1 14 0v2'],wait:['Wait','human','M12 4a8 8 0 1 0 0 16 8 8 0 1 0 0-16 M12 7v5l3 2'],choose:['Decision','decision','M12 3l9 9-9 9-9-9z M9 9l6 6 M15 9l-6 6'],exclusive:['Decision','decision','M12 3l9 9-9 9-9-9z M9 9l6 6 M15 9l-6 6'],fork:['Parallel paths','decision','M12 3l9 9-9 9-9-9z M12 8v8 M8 12h8'],join:['Join paths','decision','M12 3l9 9-9 9-9-9z M12 8v8 M8 12h8']};\nfunction presentation(node,label){const kind=String(node.type||'task').toLowerCase(),type=types[kind]||(/if|choice|gateway|parallel/.test(kind)?types.choose:['Step','neutral','M5 6h14M5 12h14M5 18h10']);let text=String(label||node.id);if(text===node.id){text=text.replace(/^(?:gw|call)[-_]/,'').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/[-_]/g,' ').replace(/\\bprod\\b/gi,'production');text=text.charAt(0).toUpperCase()+text.slice(1);}return {type,title:text,kind};}\nexport function diagramDirection(){try{return localStorage.getItem('biomerte.diagram.direction')==='vertical'?'vertical':'horizontal';}catch{return 'horizontal';}}\nexport function diagramMarkup(graph,{direction=diagramDirection(),run=null,labelFor=n=>n.name||n.label||friendlyIdentity(n.operation||n.process||n.id),selected=''}={}) {\n const layout=layoutGraph(graph,{direction}),states=nodeStates(run);layout.graph=graph;layout.options={run,labelFor,selected};\n const edges=layout.edges.map(e=>{const label=e.labelBox;return '<g class=\"flow-connection '+(e.feedback?'feedback':'')+'\"><title>'+esc(e.from+' → '+e.to+(e.label?' · '+e.label:''))+'</title><path d=\"'+e.path+'\" class=\"flow-edge-halo\"/><path d=\"'+e.path+'\" class=\"flow-edge\" marker-end=\"url(#flow-arrow)\"/>'+(label?'<g class=\"edge-caption\" transform=\"translate('+label.x+' '+label.y+')\"><rect x=\"'+(-label.w/2)+'\" y=\"-11\" width=\"'+label.w+'\" height=\"22\" rx=\"8\"/><text y=\"4\" text-anchor=\"middle\">'+esc(e.label)+'</text></g>':'')+'</g>';}).join('');\n const nodes=layout.nodes.map(n=>{const state=states[n.id]||'',p=presentation(n,labelFor(n)),type=p.type,parts=lines(p.title),radius=type[1]==='event'?38:22;\n return '<g tabindex=\"0\" role=\"button\" aria-label=\"'+esc(p.title+(state?', '+state:''))+'\" data-node=\"'+esc(n.id)+'\" transform=\"translate('+n.x+' '+n.y+')\" class=\"flow-node '+esc(state)+' kind-'+type[1]+(selected===n.id?' selected':'')+'\"><title>'+esc(p.title+' · '+type[0]+' · '+n.id+(state?' · '+state:''))+'</title><rect class=\"node-shadow\" width=\"'+n.w+'\" height=\"'+n.h+'\" rx=\"'+radius+'\"/><rect class=\"node-shape\" width=\"'+n.w+'\" height=\"'+n.h+'\" rx=\"'+radius+'\"/><rect class=\"node-grain\" x=\"1\" y=\"1\" width=\"'+(n.w-2)+'\" height=\"'+(n.h-2)+'\" rx=\"'+radius+'\"/><path class=\"node-sheen\" d=\"M24 1 H'+(n.w-24)+'\"/><g class=\"node-icon\" transform=\"translate(19 16)\"><rect width=\"32\" height=\"32\" rx=\"10\"/><path d=\"'+type[2]+'\" transform=\"translate(4 4)\"/></g><text class=\"node-type\" x=\"62\" y=\"36\">'+esc(type[0])+'</text><text class=\"node-title\" x=\"22\" y=\"'+(parts.length>1?70:77)+'\">'+parts.map((line,i)=>'<tspan x=\"22\" dy=\"'+(i?21:0)+'\">'+esc(line)+'</tspan>').join('')+'</text><text class=\"node-status\" x=\"22\" y=\"114\">'+esc(({completed:'Completed',active:'In progress',waiting:'Waiting for input',failed:'Needs attention'})[state]||'Workflow step')+'</text>'+(state?'<circle cx=\"'+(n.w-24)+'\" cy=\"31\" r=\"5\" class=\"state-marker\"/>':'')+'</g>';}).join('');\n const palettes={service:['#f9fcff','#eaf2ff'],call:['#fcfbff','#f0eafe'],decision:['#fffdf8','#fff2dc'],human:['#fffafb','#fdebf1'],event:['#f8fdfa','#e7f4ec'],neutral:['#ffffff','#f1f4f6']};\n const defs=Object.entries(palettes).map(([name,colours])=>'<linearGradient id=\"node-'+name+'\" x2=\"0\" y2=\"1\"><stop stop-color=\"'+colours[0]+'\"/><stop offset=\"1\" stop-color=\"'+colours[1]+'\"/></linearGradient>').join('');\n return {layout,html:'<svg class=\"process-svg polished-diagram\" role=\"group\" aria-label=\"Workflow diagram\" viewBox=\"0 0 '+layout.width+' '+layout.height+'\" width=\"'+layout.width+'\" height=\"'+layout.height+'\"><defs>'+defs+'<filter id=\"node-elevation\" x=\"-25%\" y=\"-25%\" width=\"150%\" height=\"170%\"><feDropShadow dx=\"0\" dy=\"6\" stdDeviation=\"8\" flood-color=\"#173b32\" flood-opacity=\".07\"/><feDropShadow dx=\"0\" dy=\"1\" stdDeviation=\"1\" flood-color=\"#173b32\" flood-opacity=\".06\"/></filter><pattern id=\"node-fibre\" width=\"5\" height=\"5\" patternUnits=\"userSpaceOnUse\"><path d=\"M0 1h1M3 4h1\" stroke=\"#294d50\" stroke-opacity=\".035\"/></pattern><marker id=\"flow-arrow\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M1 1l7 4-7 4\" fill=\"none\"/></marker></defs><g class=\"flow-connections\">'+edges+'</g><g class=\"flow-nodes\">'+nodes+'</g></svg>'};\n}\nexport function wireDiagram(container,layout,onSelect) {\n const viewport=container.querySelector('.diagram-viewport'),svg=container.querySelector('svg');if(!svg)return;\n let scale=1;\n function zoom(value,anchor=null){const old=scale;scale=Math.max(.12,Math.min(3,value));const cx=anchor?.x??viewport.clientWidth/2,cy=anchor?.y??viewport.clientHeight/2,px=(viewport.scrollLeft+cx)/old,py=(viewport.scrollTop+cy)/old;svg.style.width=layout.width*scale+'px';svg.style.height=layout.height*scale+'px';container.querySelector('[data-zoom-value]').textContent=Math.round(scale*100)+'%';viewport.scrollLeft=Math.max(0,px*scale-cx);viewport.scrollTop=Math.max(0,py*scale-cy);}\n const fit=()=>{zoom(Math.min(1,(viewport.clientWidth-64)/layout.width));viewport.scrollLeft=0;viewport.scrollTop=0;};\n container.querySelector('[data-zoom-in]').onclick=()=>zoom(scale*1.2);\n container.querySelector('[data-zoom-out]').onclick=()=>zoom(scale/1.2);\n container.querySelector('[data-zoom-fit]').onclick=fit;\n container.querySelector('[data-zoom-all]').onclick=()=>{zoom(Math.min((viewport.clientWidth-64)/layout.width,(viewport.clientHeight-64)/layout.height));viewport.scrollLeft=0;viewport.scrollTop=0;};\n container.querySelector('[data-zoom-reset]').onclick=()=>zoom(1);\n const full=container.querySelector('[data-fullscreen]');function expand(value){container.classList.toggle('diagram-expanded',value);full.textContent=value?'Close full screen':'Full screen';full.setAttribute('aria-pressed',String(value));viewport.focus({preventScroll:true});}full.onclick=()=>expand(!container.classList.contains('diagram-expanded'));container.onkeydown=e=>{if(e.key==='Escape'&&container.classList.contains('diagram-expanded')){e.preventDefault();expand(false);full.focus({preventScroll:true});}};\n for(const node of svg.querySelectorAll('[data-node]')){node.onclick=()=>onSelect(node.dataset.node);node.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onSelect(node.dataset.node);}};}\n viewport.tabIndex=0;viewport.setAttribute('aria-label','Process canvas. Drag to pan; use plus and minus to zoom.');\n viewport.onkeydown=e=>{if(e.target!==viewport)return;if(['+','=','-','0'].includes(e.key)){e.preventDefault();if(e.key==='0')fit();else zoom(scale*(e.key==='-'?1/1.2:1.2));}};\n viewport.onwheel=e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();const box=viewport.getBoundingClientRect();zoom(scale*Math.exp(-e.deltaY*.007),{x:e.clientX-box.left,y:e.clientY-box.top});};\n let drag=null;viewport.onpointerdown=e=>{if(e.target.closest('[data-node]')||e.button!==0)return;drag={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging');};viewport.onpointermove=e=>{if(!drag)return;viewport.scrollLeft=drag.left-e.clientX+drag.x;viewport.scrollTop=drag.top-e.clientY+drag.y;};const release=()=>{drag=null;viewport.classList.remove('dragging');};viewport.onpointerup=release;viewport.onpointercancel=release;viewport.onlostpointercapture=release;\n for(const button of container.querySelectorAll('[data-direction]')){button.setAttribute('aria-pressed',String(button.dataset.direction===layout.direction));button.onclick=()=>{const direction=button.dataset.direction;if(direction===layout.direction)return;try{localStorage.setItem('biomerte.diagram.direction',direction);}catch{}const selected=svg.querySelector('.flow-node.selected')?.dataset.node||'';const drawn=diagramMarkup(layout.graph,{...layout.options,selected,direction});viewport.innerHTML=drawn.html;wireDiagram(container,drawn.layout,onSelect);};}\n zoom(Math.max(.8,Math.min(1,(viewport.clientWidth-64)/layout.width)));viewport.scrollTop=0;viewport.scrollLeft=layout.direction==='horizontal'?0:Math.max(0,(layout.width*scale-viewport.clientWidth)/2);\n const active=svg.querySelector('.flow-node.active,.flow-node.waiting,.flow-node.failed');const current=layout.nodes.find(n=>n.id===active?.dataset.node);if(current){viewport.scrollTop=Math.max(0,current.y*scale-viewport.clientHeight*.3);if(layout.direction==='horizontal')viewport.scrollLeft=Math.max(0,current.x*scale-viewport.clientWidth*.3);}\n}\nexport const diagramToolbar='<div class=\"diagram-toolbar\"><span class=\"legend\" aria-label=\"Execution states\"><span><i class=\"completed\"></i>Completed</span><span><i class=\"active\"></i>In progress</span><span><i class=\"waiting\"></i>Waiting</span><span><i class=\"failed\"></i>Needs attention</span></span><div class=\"canvas-controls\"><div class=\"direction-control\" role=\"group\" aria-label=\"Flow direction\"><button data-direction=\"horizontal\" aria-pressed=\"true\" title=\"Flow from left to right\">Left to right</button><button data-direction=\"vertical\" aria-pressed=\"false\" title=\"Flow from top to bottom\">Top to bottom</button></div><div class=\"zoom-control\"><button data-zoom-out aria-label=\"Zoom out\" title=\"Zoom out (−)\">−</button><button data-zoom-reset data-zoom-value title=\"Actual size\">100%</button><button data-zoom-in aria-label=\"Zoom in\" title=\"Zoom in (+)\">＋</button></div><button data-zoom-fit>Fit width</button><button data-zoom-all>Fit diagram</button><button data-fullscreen>Full screen</button></div></div><div class=\"canvas-guidance\"><span>Drag to explore</span><span>Click any step for details</span><span>⌘ / Ctrl + scroll to zoom</span></div>';\n";
